<template><article class="card payment"><div><b>{{payment.fee_type}}</b><p>{{payment.month}} · ¥{{payment.amount.toFixed(2)}}</p></div><div><el-tag :type="payment.status==='paid'?'success':'warning'">{{payment.status==='paid'?'已缴费':'待缴费'}}</el-tag><el-button v-if="payment.status!=='paid'" size="small" type="primary" @click="$emit('pay',payment.id)">模拟支付</el-button></div></article></template><script setup lang="ts">import type{Payment}from'../../types';defineProps<{payment:Payment}>();defineEmits<{pay:[id:number]}>()</script>
